INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(842042, 95113, 20214, '<td valign="top">Cropped a little too much, otherwise a good photo!</td>', 'Cropped a little too much, otherwise a good photo!', '2004-08-04 12:29:41.000000', NULL, 1),
(842044, 94879, 19670, '<td valign="top">Really nice picture! Has a great painted look. But, is that a "MINI" car? Is it miniature raindrops? What''s being strived for (title)?</td>', 'Really nice picture! Has a great painted look. But, is that a "MINI" car? Is it miniature raindrops? What''s being strived for (title)?', '2004-08-04 12:30:10.000000', NULL, 1),
(842046, 95604, 24413, '<td valign="top">Very creative!</td>', 'Very creative!', '2004-08-04 12:30:33.000000', NULL, 1),
(842048, 94826, 6132, '<td valign="top">Very cute! Well composed, nice use of dof and good use of light. Good luck with the challenge.</td>', 'Very cute! Well composed, nice use of dof and good use of light. Good luck with the challenge.', '2004-08-04 12:31:33.000000', NULL, 1),
(842049, 95701, 24413, '<td valign="top">Wow!  This is amazing!  Very creative!</td>', 'Wow!  This is amazing!  Very creative!', '2004-08-04 12:31:51.000000', NULL, 1),
(842050, 95489, 19670, '<td valign="top">Good idea! If only you could have made the bike "fly" and still compare to something bigger (like you did with the keyboard).</td>', 'Good idea! If only you could have made the bike "fly" and still compare to something bigger (like you did with the keyboard).', '2004-08-04 12:31:56.000000', NULL, 1),
(842055, 95593, 25000, '<td valign="top">Excellent, very amusing :)</td>', 'Excellent, very amusing :)', '2004-08-04 12:33:02.000000', NULL, 1),
(842057, 95645, 24413, '<td valign="top">I like this idea but I wish the smaller car had been positioned differently.</td>', 'I like this idea but I wish the smaller car had been positioned differently.', '2004-08-04 12:33:16.000000', NULL, 1),
(842060, 94308, 6132, '<td valign="top">Brilliant! I think the contrast of the colours of the subject and background work really well with this image.  Nice use of lighting.</td>', 'Brilliant! I think the contrast of the colours of the subject and background work really well with this image.  Nice use of lighting.', '2004-08-04 12:33:31.000000', NULL, 1),
(842061, 94885, 10720, '<td valign="top">I like the picture, but if the person is what I am to use for perspective the snow looks huge not minature. At least larger then most people will have seen shoveling their driveways. <br/>I like the colors being the person, it draws your eye to them. The placement of one foot back is a bit distrubing as it looks like they only have half a leg. A title to show that person not the snow is the minature would have helped this photo, As would a powerful flash to bring some more contrast into the shadowed area. Hope the comments help sorry I can''t rate this photo that high.</td>', 'I like the picture, but if the person is what I am to use for perspective the snow looks huge not minature. At least larger then most people will have seen shoveling their driveways. I like the colors being the person, it draws your eye to them. The placement of one foot back is a bit distrubing as it looks like they only have half a leg. A title to show that person not the snow is the minature would have helped this photo, As would a powerful flash to bring some more contrast into the shadowed area. Hope the comments help sorry I can''t rate this photo that high.', '2004-08-04 12:33:53.000000', NULL, 1),
(842066, 95463, 24413, '<td valign="top">Very unique and a good shot!</td>', 'Very unique and a good shot!', '2004-08-04 12:34:27.000000', NULL, 1),
(842069, 95587, 24413, '<td valign="top">Very creative shot!</td>', 'Very creative shot!', '2004-08-04 12:36:10.000000', NULL, 1),
(842070, 95570, 10720, '<td valign="top">I really like that you found three, It is still tough to tell scale in this shot since leaves come in all sizes. Also unfortunetly the one part that seems out of focus in this shot is also on the one third line and where the leading lines of the leaf lead too giving it undo attention. My final wish is that the littlest snail the "minature" one had more of it''s head out to match the others.</td>', 'I really like that you found three, It is still tough to tell scale in this shot since leaves come in all sizes. Also unfortunetly the one part that seems out of focus in this shot is also on the one third line and where the leading lines of the leaf lead too giving it undo attention. My final wish is that the littlest snail the "minature" one had more of it''s head out to match the others.', '2004-08-04 12:36:19.000000', NULL, 1),
(842074, 95613, 10720, '<td valign="top">Very nice! I really like the spoon, the red colours, the pot, I would have skipped the cracker? behind the soup can, to me the white organic shape takes away for the curves and straight lines of the rest of the objects. The reflections on the bottom of the spoon are a bit distacting as well.  Still I expect this to be in the top ten for the challenge. - 8</td>', 'Very nice! I really like the spoon, the red colours, the pot, I would have skipped the cracker? behind the soup can, to me the white organic shape takes away for the curves and straight lines of the rest of the objects. The reflections on the bottom of the spoon are a bit distacting as well.  Still I expect this to be in the top ten for the challenge. - 8', '2004-08-04 12:38:36.000000', NULL, 1),
(842075, 95421, 24413, '<td valign="top">Good idea but it would have been nice to see this on a real piano or on some life size sheet music.</td>', 'Good idea but it would have been nice to see this on a real piano or on some life size sheet music.', '2004-08-04 12:38:42.000000', NULL, 1),
(842077, 94351, 24413, '<td valign="top">Very creative.</td>', 'Very creative.', '2004-08-04 12:39:20.000000', NULL, 1),
(842078, 95193, 19072, '<td valign="top">I wonder how it would look with the camera placed at the soldiers heads height?  maybe more realistic!    anyway I like it a lot!</td>', 'I wonder how it would look with the camera placed at the soldiers heads height?  maybe more realistic!    anyway I like it a lot!', '2004-08-04 12:41:27.000000', NULL, 1),
(842081, 94351, 2764, '<td valign="top">This is really nice.  Seems like half the people got the miniature part but forgot that it also had to be an interesting photo.  Here a clever idea is also a well executed image that tells a funny story.  Here is what  like: focus, movement both of water and implied movement of the surfer, colors muted blue contrasts with the colorful surfer, thirds, leading lines are esp nice:  Since the faucet is the first visual draw, the image reads from right to left which is a more dynamic direction. so, the faucet leads in, the water lines lead left, the angle of the surfer leads back into the image indead of continuring the line out.   As soon as the voters eye is lead off the page his brain thinks "Done, next please".  If you can draw the quick viewer back in he''ll take another look and appresicate your picture more.</td>', 'This is really nice.  Seems like half the people got the miniature part but forgot that it also had to be an interesting photo.  Here a clever idea is also a well executed image that tells a funny story.  Here is what  like: focus, movement both of water and implied movement of the surfer, colors muted blue contrasts with the colorful surfer, thirds, leading lines are esp nice:  Since the faucet is the first visual draw, the image reads from right to left which is a more dynamic direction. so, the faucet leads in, the water lines lead left, the angle of the surfer leads back into the image indead of continuring the line out.   As soon as the voters eye is lead off the page his brain thinks "Done, next please".  If you can draw the quick viewer back in he''ll take another look and appresicate your picture more.', '2004-08-04 12:43:30.000000', NULL, 1),
(842083, 95633, 1570, '<td valign="top">oh wow, i did the same thing, well, kind of... with absolut mini, too... they are just so-o-o-o-o cute, aren''t they... well, good luck to you! i see you have the same problem as i did, too - the letters on giant bottles are nice and focused, and not so on the mini... so, i went with a different approach...</td>', 'oh wow, i did the same thing, well, kind of... with absolut mini, too... they are just so-o-o-o-o cute, aren''t they... well, good luck to you! i see you have the same problem as i did, too - the letters on giant bottles are nice and focused, and not so on the mini... so, i went with a different approach...', '2004-08-04 12:44:29.000000', NULL, 1),
(842088, 94870, 2764, '<td valign="top">hmmm - I hate a tilted horizon and it isn''t clear if this is tilted or straight so it just ends up being unsettling.  The foreground feels off while the background feels straight.  You''d be surprised how many points you can lose when the viewer feels slightly disoriented by the horizon line.  Either tilt a lot for effect or get it straight.</td>', 'hmmm - I hate a tilted horizon and it isn''t clear if this is tilted or straight so it just ends up being unsettling.  The foreground feels off while the background feels straight.  You''d be surprised how many points you can lose when the viewer feels slightly disoriented by the horizon line.  Either tilt a lot for effect or get it straight.', '2004-08-04 12:46:20.000000', NULL, 1),
(842089, 95629, 24413, '<td valign="top">I think this is the best picture. I hope you win!</td>', 'I think this is the best picture. I hope you win!', '2004-08-04 12:46:24.000000', NULL, 1),
(842090, 95682, 10720, '<td valign="top">A rose is a tough choice for a size challenge, since they have roses that are small, as well as very large. (See a couple of entries that used roses) A normal red rose is say 2 inches across, and a normal perfume bottle is about the same. I am afraid it would have been more effective to use the perfume bottles as the point of reference and a smaller rose. Instead of a rose, could have used something else a women would have to give a sense of scale. I really can''t tell if these objects are one inch high, two inches, three etc...  <br/>Other points, the lines on the paper are distacting, and the yellow cast implies an auto white balance and then inside lighting. There is no one spot for my eyes to rest on, but there is no circle of leading lines to draw my eyes to see the whole picture either. I would have prefered the image with just the rose and the right most bottle. the green stem leading in one direction and the "leaf" on the bottle (flame?) leading in the other both bring the eye to the right one third line, and the contrast between the rose and the bottle''s color</td>', 'A rose is a tough choice for a size challenge, since they have roses that are small, as well as very large. (See a couple of entries that used roses) A normal red rose is say 2 inches across, and a normal perfume bottle is about the same. I am afraid it would have been more effective to use the perfume bottles as the point of reference and a smaller rose. Instead of a rose, could have used something else a women would have to give a sense of scale. I really can''t tell if these objects are one inch high, two inches, three etc...  Other points, the lines on the paper are distacting, and the yellow cast implies an auto white balance and then inside lighting. There is no one spot for my eyes to rest on, but there is no circle of leading lines to draw my eyes to see the whole picture either. I would have prefered the image with just the rose and the right most bottle. the green stem leading in one direction and the "leaf" on the bottle (flame?) leading in the other both bring the eye to the right one third line, and the contrast between the rose and the bottle''s color', '2004-08-04 12:46:24.000000', NULL, 1),
(842092, 95640, 24413, '<td valign="top">Very creative!</td>', 'Very creative!', '2004-08-04 12:47:10.000000', NULL, 1),
(842094, 95008, 9083, '<td valign="top">What a great photo!  Love it! 9</td>', 'What a great photo!  Love it! 9', '2004-08-04 12:49:44.000000', NULL, 1),
(842095, 95437, 10720, '<td valign="top">The challgne was to take a minature of a larger object, this seems to be the opposite of what the challenge requested. Nor are plants a good use of minature since they come in all shapes and sizes.<br/> <br/>That aside I like the leading lines and the DOF in general. Also got a nice blue sky, but even if it met the challenge I suspect this picture would be mid 5''s,</td>', 'The challgne was to take a minature of a larger object, this seems to be the opposite of what the challenge requested. Nor are plants a good use of minature since they come in all shapes and sizes. That aside I like the leading lines and the DOF in general. Also got a nice blue sky, but even if it met the challenge I suspect this picture would be mid 5''s,', '2004-08-04 12:50:04.000000', NULL, 1),
(842097, 95228, 24413, '<td valign="top">Very unique!</td>', 'Very unique!', '2004-08-04 12:51:26.000000', NULL, 1),
