(845360, 94954, 23561, '<td valign="top">I wanted to give this a higher score because I''m a big Coke drinker. It''s a running joke kind of with me. However, I felt the mini coke should have been the focal point rather than the glass. I like the glass though and the lighting looks ok to me.</td>', 'I wanted to give this a higher score because I''m a big Coke drinker. It''s a running joke kind of with me. However, I felt the mini coke should have been the focal point rather than the glass. I like the glass though and the lighting looks ok to me.', '2004-08-05 19:45:23.000000', NULL, 1),
(845363, 95705, 23561, '<td valign="top">Not bad, but its a bit to bright. And where are the red ones?</td>', 'Not bad, but its a bit to bright. And where are the red ones?', '2004-08-05 19:46:13.000000', NULL, 1),
(845399, 95570, 20066, '<td valign="top">Looks very big to me</td>', 'Looks very big to me', '2004-08-05 20:19:04.000000', NULL, 1),
