INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(845626, 94359, 22385, '<td valign="top">Centered well.  Lighting is pretty good.  Good focus.  Too bad it''s not finished!</td>', 'Centered well.  Lighting is pretty good.  Good focus.  Too bad it''s not finished!', '2004-08-05 22:45:05.000000', NULL, 1),
(845630, 95684, 22385, '<td valign="top">Your top three fingers come out of focus at the tips.  This doesn''t kill the image, but it is distracting.  I think there are other perspectives you could have used to make the photo more interesting.  I hate it to say it, but the photo kind of bores me.  :(</td>', 'Your top three fingers come out of focus at the tips.  This doesn''t kill the image, but it is distracting.  I think there are other perspectives you could have used to make the photo more interesting.  I hate it to say it, but the photo kind of bores me.  :(', '2004-08-05 22:46:52.000000', NULL, 1),
(845631, 95363, 25033, '<td valign="top">Top notch, very clever...I love it.  The car would have really stood out in more vibrant color, nonetheless great composition!  Good luck!</td>', 'Top notch, very clever...I love it.  The car would have really stood out in more vibrant color, nonetheless great composition!  Good luck!', '2004-08-05 22:46:55.000000', NULL, 1),
(845636, 95685, 22385, '<td valign="top">Interesting choice of lighting, though I''m not sure if it works for you.  It''s difficult to know what I''m supposed to be looking at and what the demonstration of "miniature" is in this challenge.</td>', 'Interesting choice of lighting, though I''m not sure if it works for you.  It''s difficult to know what I''m supposed to be looking at and what the demonstration of "miniature" is in this challenge.', '2004-08-05 22:48:16.000000', NULL, 1),
(845638, 95696, 25033, '<td valign="top">Cool...the lighting looks a little dark though.  Good luck!</td>', 'Cool...the lighting looks a little dark though.  Good luck!', '2004-08-05 22:48:39.000000', NULL, 1),
(845645, 94689, 22385, '<td valign="top">Is the elephant made out of glass?  Or is this a clash of glass and wood?  Not sure what the intent was in this photo with regard to the foreground and background.  The elephant is somewhat blurry toward the back.  All of the colors in this image just seem to flow into each other.</td>', 'Is the elephant made out of glass?  Or is this a clash of glass and wood?  Not sure what the intent was in this photo with regard to the foreground and background.  The elephant is somewhat blurry toward the back.  All of the colors in this image just seem to flow into each other.', '2004-08-05 22:50:25.000000', NULL, 1),
(845649, 95482, 23561, '<td valign="top">Didn''t meet the challenge. Guess my vision was skewed! Overall good quality. I don''t like the brown on brown. Could be a little brighter.</td>', 'Didn''t meet the challenge. Guess my vision was skewed! Overall good quality. I don''t like the brown on brown. Could be a little brighter.', '2004-08-05 22:53:26.000000', NULL, 1),
(845653, 94734, 22385, '<td valign="top">It appears that you were using the sign to show humor, with the dog looking small (hence, the "miniature" theme).  I think it''s a stretch for the challenge, but I do think it is really funny.  Lighting, focus, and details are all good.  This is an average photo to me in this particular challenge.</td>', 'It appears that you were using the sign to show humor, with the dog looking small (hence, the "miniature" theme).  I think it''s a stretch for the challenge, but I do think it is really funny.  Lighting, focus, and details are all good.  This is an average photo to me in this particular challenge.', '2004-08-05 22:55:12.000000', NULL, 1),
(845655, 95667, 23561, '<td valign="top">Not a bad concept, the different patterns clash to me.</td>', 'Not a bad concept, the different patterns clash to me.', '2004-08-05 22:55:32.000000', NULL, 1),
(845658, 95654, 22385, '<td valign="top">I like the use of spotlighting the Barbie in the center.   I wish the focus was better, though.  The centered Barbie has a soft focus to it, while the rest of the Barbies just look washed out, taking away from the picture.  A bit noisy.</td>', 'I like the use of spotlighting the Barbie in the center.   I wish the focus was better, though.  The centered Barbie has a soft focus to it, while the rest of the Barbies just look washed out, taking away from the picture.  A bit noisy.', '2004-08-05 22:56:34.000000', NULL, 1),
(845659, 94985, 23561, '<td valign="top">Don''t like the background. More of the photo is out of focus rather than in focus and seems to distract.</td>', 'Don''t like the background. More of the photo is out of focus rather than in focus and seems to distract.', '2004-08-05 22:57:34.000000', NULL, 1),
(845660, 94195, 11895, '<td valign="top">good idea but the way you''ve done the colors detracts, the front figure doesn''t stand out from the background enough</td>', 'good idea but the way you''ve done the colors detracts, the front figure doesn''t stand out from the background enough', '2004-08-05 22:57:43.000000', NULL, 1),
(845661, 95632, 22385, '<td valign="top">I like the concept of this image.  However, I think the blurry silhouettes compromise the quality of the image; too much blurriness for the majority of the picture.  I find my eyes moving toward the bright lighting in the upper left hand corner.</td>', 'I like the concept of this image.  However, I think the blurry silhouettes compromise the quality of the image; too much blurriness for the majority of the picture.  I find my eyes moving toward the bright lighting in the upper left hand corner.', '2004-08-05 22:58:51.000000', NULL, 1),
(845663, 95670, 25033, '<td valign="top">Very cool indeed!</td>', 'Very cool indeed!', '2004-08-05 22:59:23.000000', NULL, 1),
(845664, 95643, 22385, '<td valign="top">I like how the miniature car has stickers on it just like the big one.  Unfortunate that the flash/sun is in the window of the big car.  Some pixellation in the image.</td>', 'I like how the miniature car has stickers on it just like the big one.  Unfortunate that the flash/sun is in the window of the big car.  Some pixellation in the image.', '2004-08-05 23:00:08.000000', NULL, 1),
(845666, 95113, 25033, '<td valign="top">Cool.</td>', 'Cool.', '2004-08-05 23:00:37.000000', NULL, 1),
(845668, 95078, 23561, '<td valign="top">Good focus and I like the pearls for the miniataure contrast.  I don''t like the boarder though. I think it detracts from the golden hue of the pearls. Maybe a green would work better. I say that because I do like the green contrast to the reflected pearl in the bottom left side.</td>', 'Good focus and I like the pearls for the miniataure contrast.  I don''t like the boarder though. I think it detracts from the golden hue of the pearls. Maybe a green would work better. I say that because I do like the green contrast to the reflected pearl in the bottom left side.', '2004-08-05 23:01:13.000000', NULL, 1),
(845669, 95536, 22385, '<td valign="top">In some ways, I really like this image.  Excellent focus on the planet.  Colors in background create a nice effect.  I think there could have been ways to make the image better, though.  For instance, having different lighting so that there is no shadow from the model.</td>', 'In some ways, I really like this image.  Excellent focus on the planet.  Colors in background create a nice effect.  I think there could have been ways to make the image better, though.  For instance, having different lighting so that there is no shadow from the model.', '2004-08-05 23:01:52.000000', NULL, 1),
(845671, 94759, 22385, '<td valign="top">A little too bright, as the tires are just a tad washed out.  Fairly good detail on the car.  I don''t think negative space in this image works - it actually distracts the eyes.</td>', 'A little too bright, as the tires are just a tad washed out.  Fairly good detail on the car.  I don''t think negative space in this image works - it actually distracts the eyes.', '2004-08-05 23:02:52.000000', NULL, 1),
(845673, 95675, 22385, '<td valign="top">So we have a miniature cup here.  The lighting is pretty good, as is the focus and detail.  But I see competing images here that distract the eyes.  For me, it just feels like there''s too much going on.</td>', 'So we have a miniature cup here.  The lighting is pretty good, as is the focus and detail.  But I see competing images here that distract the eyes.  For me, it just feels like there''s too much going on.', '2004-08-05 23:04:22.000000', NULL, 1),
(845675, 94197, 23561, '<td valign="top">Hard to comment (and vote) on this one because I had a similar idea. Good concept! roses are a little out of focus and I like a sharper image. At first I liked the texture added by the beads but they may distract from the focus.</td>', 'Hard to comment (and vote) on this one because I had a similar idea. Good concept! roses are a little out of focus and I like a sharper image. At first I liked the texture added by the beads but they may distract from the focus.', '2004-08-05 23:05:58.000000', NULL, 1),
(845676, 94855, 22385, '<td valign="top">Interesting use of lighting.  However, the oval shape to the lighting gives the unfortunate illusion that the quarter and lip balm is leaning to the lower right.  Focus is fairly good.</td>', 'Interesting use of lighting.  However, the oval shape to the lighting gives the unfortunate illusion that the quarter and lip balm is leaning to the lower right.  Focus is fairly good.', '2004-08-05 23:06:11.000000', NULL, 1),
(845678, 94359, 23561, '<td valign="top">Good clear photo, meets the challenge, good concept. Just doesn''t pop for me.</td>', 'Good clear photo, meets the challenge, good concept. Just doesn''t pop for me.', '2004-08-05 23:07:51.000000', NULL, 1),
(845680, 95581, 22385, '<td valign="top">Good focus on the model, except for some areas toward the northwest end of Africa - but I think it is due to the competing stonework in the model.  Not so much your fault.  I would have used a different pattern to set the model on. The bumps in the tabletop pattern are a bit distracting.</td>', 'Good focus on the model, except for some areas toward the northwest end of Africa - but I think it is due to the competing stonework in the model.  Not so much your fault.  I would have used a different pattern to set the model on. The bumps in the tabletop pattern are a bit distracting.', '2004-08-05 23:08:10.000000', NULL, 1),
(845684, 94540, 23561, '<td valign="top">Really liked the use of pineapples. Makes the picture pop. Problem is it only pops at the bottom. Maybe if lighting was different and the sword shined more. Good photo.</td>', 'Really liked the use of pineapples. Makes the picture pop. Problem is it only pops at the bottom. Maybe if lighting was different and the sword shined more. Good photo.', '2004-08-05 23:10:07.000000', NULL, 1),
(845685, 95204, 22385, '<td valign="top">I am lost in terms of what the miniature is in this challenge.  I''m sure that comment is annoying to you!  Hopefully, when the challenge is over, we can get more of an explanation.  Lighting, contrast, and focus are all good.  Seems a bit too pixelated in the upper right hand corner.</td>', 'I am lost in terms of what the miniature is in this challenge.  I''m sure that comment is annoying to you!  Hopefully, when the challenge is over, we can get more of an explanation.  Lighting, contrast, and focus are all good.  Seems a bit too pixelated in the upper right hand corner.', '2004-08-05 23:10:15.000000', NULL, 1),
(845686, 94604, 22385, '<td valign="top">A unique and interesting deviation from the norm of creating the "miniature" in many photos in this challenge.  It''s not an appealing image, overall, but it''s a good concept.</td>', 'A unique and interesting deviation from the norm of creating the "miniature" in many photos in this challenge.  It''s not an appealing image, overall, but it''s a good concept.', '2004-08-05 23:11:35.000000', NULL, 1),
(845689, 94761, 23561, '<td valign="top">Photo seems soft or slightly blurred for some reason.</td>', 'Photo seems soft or slightly blurred for some reason.', '2004-08-05 23:12:19.000000', NULL, 1),
(845690, 95055, 22385, '<td valign="top">The lack of focus in the majority of the photo kills my eyes.  A bit overexposed on the object in the top of the photo.</td>', 'The lack of focus in the majority of the photo kills my eyes.  A bit overexposed on the object in the top of the photo.', '2004-08-05 23:12:54.000000', NULL, 1),
(845692, 94438, 23939, '<td valign="top">whats mini here</td>', 'whats mini here', '2004-08-05 23:13:23.000000', NULL, 1),
(845694, 94759, 23939, '<td valign="top">this doesnt convey me thtat it is mini</td>', 'this doesnt convey me thtat it is mini', '2004-08-05 23:15:45.000000', NULL, 1),
(845695, 95344, 23561, '<td valign="top">Nice concept. Don''t care for the black background.  Excellent focus.</td>', 'Nice concept. Don''t care for the black background.  Excellent focus.', '2004-08-05 23:16:26.000000', NULL, 1),
(845698, 95639, 23561, '<td valign="top">Not a bad picture. Not sure I like the pink background. It pops, but then the rest looks kind of boring to me. Just my opinion.</td>', 'Not a bad picture. Not sure I like the pink background. It pops, but then the rest looks kind of boring to me. Just my opinion.', '2004-08-05 23:18:02.000000', NULL, 1),
(845702, 95228, 23561, '<td valign="top">Are these dried flowers? Not bad. Good focus. Don''t like the boarder. Background is kind of dark and flowers don''t stand out.</td>', 'Are these dried flowers? Not bad. Good focus. Don''t like the boarder. Background is kind of dark and flowers don''t stand out.', '2004-08-05 23:19:49.000000', NULL, 1),
