(846141, 95525, 22245, '<td valign="top">What an adorable photo! I love the expression on the animal''s faces.</td>', 'What an adorable photo! I love the expression on the animal''s faces.', '2004-08-06 06:04:14.000000', NULL, 1),
(846143, 94885, 22245, '<td valign="top">this photo has a wonderful composition, however I think it may be a little on the underexposed side.</td>', 'this photo has a wonderful composition, however I think it may be a little on the underexposed side.', '2004-08-06 06:05:10.000000', NULL, 1),
(846150, 94736, 24128, '<td valign="top">I love the classic perspective look of this pic, I fear that many images rely on an ''in our face'' abstract approach, well done for getting a ''classic'' approach right in more ways than one</td>', 'I love the classic perspective look of this pic, I fear that many images rely on an ''in our face'' abstract approach, well done for getting a ''classic'' approach right in more ways than one', '2004-08-06 06:27:19.000000', NULL, 1),
