(846154, 95664, 24128, '<td valign="top">the foreground makes it clear that there is nothing miniature in the pic - nice scene though</td>', 'the foreground makes it clear that there is nothing miniature in the pic - nice scene though', '2004-08-06 06:33:55.000000', NULL, 1),
(846155, 94438, 24128, '<td valign="top">this appears to be a close up of a bracket - i''m not aware of anything miniature here</td>', 'this appears to be a close up of a bracket - i''m not aware of anything miniature here', '2004-08-06 06:34:47.000000', NULL, 1),
(846157, 94507, 24128, '<td valign="top">i just noticed the new growth (after the 3rd view of the pic) so I''ll up my vote, clearly as it took a few views to ''get it'' some form of clarity is needed</td>', 'i just noticed the new growth (after the 3rd view of the pic) so I''ll up my vote, clearly as it took a few views to ''get it'' some form of clarity is needed', '2004-08-06 06:38:12.000000', NULL, 1),
