(846189, 94838, 24983, '<td valign="top">shallowc depth of feild works well here would have liked the pawn a little more to the right as the bottom is cut off</td>', 'shallowc depth of feild works well here would have liked the pawn a little more to the right as the bottom is cut off', '2004-08-06 07:17:49.000000', NULL, 1),
