(846420, 94748, 21245, '<td valign="top">I always thought the ground crawling gunmen were the coolest Army Men in the bag!  I like the little plant in the pic, I think it adds a lot.</td>', 'I always thought the ground crawling gunmen were the coolest Army Men in the bag!  I like the little plant in the pic, I think it adds a lot.', '2004-08-06 11:45:38.000000', NULL, 1),
(846434, 94838, 21245, '<td valign="top">It''s like the Lord of the Rings: The Twin Towers, "What''s going on?"  "Would you like me to describe it for you?  Or shall I get you a box?"  Okay, maybe that''s lame, but I like the picture!</td>', 'It''s like the Lord of the Rings: The Twin Towers, "What''s going on?"  "Would you like me to describe it for you?  Or shall I get you a box?"  Okay, maybe that''s lame, but I like the picture!', '2004-08-06 11:49:24.000000', NULL, 1),
(846441, 94294, 19751, '<td valign="top">that bun doesnt look too healthy... haha</td>', 'that bun doesnt look too healthy... haha', '2004-08-06 11:53:04.000000', NULL, 1),
(846446, 95523, 3087, '<td valign="top">Nicely isolated within the frame and nice use of negative space to create more of a sense of the scale. Some might wonder how, with nothing else in the frame, it''s obvious that your subject is miniaturised but the size of the leaves compared to trunk/ branches and also the style of the container are both very strongly recognisable to any bonsai fan. 9</td>', 'Nicely isolated within the frame and nice use of negative space to create more of a sense of the scale. Some might wonder how, with nothing else in the frame, it''s obvious that your subject is miniaturised but the size of the leaves compared to trunk/ branches and also the style of the container are both very strongly recognisable to any bonsai fan. 9', '2004-08-06 11:56:30.000000', NULL, 1),
(846448, 95078, 3087, '<td valign="top">Love the golden colour palette and the juxtaposition of two items that seem to have no connection. Wish the funnel of the train reflection were not cropped. 8</td>', 'Love the golden colour palette and the juxtaposition of two items that seem to have no connection. Wish the funnel of the train reflection were not cropped. 8', '2004-08-06 11:57:25.000000', NULL, 1),
(846449, 95437, 19751, '<td valign="top">waaaaaaaaaaaaaaay too compressed!!!</td>', 'waaaaaaaaaaaaaaay too compressed!!!', '2004-08-06 11:58:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(846450, 95536, 3087, '<td valign="top">Strangely appealing for such a simple image. I like the way the background splits into two complimentary orange-yellow - I assume that''s just clever use of shadow? I''d probably move the globe just a touch leftwards but not much at all. 8</td>', 'Strangely appealing for such a simple image. I like the way the background splits into two complimentary orange-yellow - I assume that''s just clever use of shadow? I''d probably move the globe just a touch leftwards but not much at all. 8', '2004-08-06 11:58:45.000000', NULL, 1),
(846451, 94879, 19751, '<td valign="top">i''m sure you probably already know this... but this picture would be awesome if it wasnt taken through a rainy windshield. true shame because it looks beautiful otherwise</td>', 'i''m sure you probably already know this... but this picture would be awesome if it wasnt taken through a rainy windshield. true shame because it looks beautiful otherwise', '2004-08-06 11:59:21.000000', NULL, 1),
(846453, 94278, 3087, '<td valign="top">This is beautifully done - the composition just works so well. Using the foot as the display pedestal for the miniature shoe works well not only in terms of showing scale but also in terms of shape and colour. Very nice. 8</td>', 'This is beautifully done - the composition just works so well. Using the foot as the display pedestal for the miniature shoe works well not only in terms of showing scale but also in terms of shape and colour. Very nice. 8', '2004-08-06 12:00:11.000000', NULL, 1),
(846456, 95570, 3087, '<td valign="top">How did you get them to do that? I''ll be even more surprised if you tell me it was a natural occurence! I think the content itself is stronger than the image as a whole - composition isn''t great for me - I think a landscape would work better with the "shape" of the snail group as a whole - and the top third seems a little dark. Also think it''s a shame that the shell of the middle snail is cropped slightly by the right edge of the frame. 8</td>', 'How did you get them to do that? I''ll be even more surprised if you tell me it was a natural occurence! I think the content itself is stronger than the image as a whole - composition isn''t great for me - I think a landscape would work better with the "shape" of the snail group as a whole - and the top third seems a little dark. Also think it''s a shame that the shell of the middle snail is cropped slightly by the right edge of the frame. 8', '2004-08-06 12:02:15.000000', NULL, 1),
(846458, 95539, 19751, '<td valign="top">i think this pic could do without the hand in it... but still very nice</td>', 'i think this pic could do without the hand in it... but still very nice', '2004-08-06 12:03:17.000000', NULL, 1),
(846459, 95606, 11895, '<td valign="top">creative idea, a lighter background would have made the ant stand out better</td>', 'creative idea, a lighter background would have made the ant stand out better', '2004-08-06 12:04:33.000000', NULL, 1),
(846464, 95674, 19751, '<td valign="top">too overexposed on most of the picture</td>', 'too overexposed on most of the picture', '2004-08-06 12:07:42.000000', NULL, 1),
