(848005, 95593, 24024, '<td valign="top">Oh gross! But it''s cute anyways! Good Job</td>', 'Oh gross! But it''s cute anyways! Good Job', '2004-08-07 13:07:20.000000', NULL, 1),
(848014, 95259, 18799, '<td valign="top">These are all in proportion - nothing to tell me they are miniature versions of the real thing, other than I know it''s a model.   Doesn''t meet the challenge IMO.   It IS a well lit and well composed photo though.  Upon my second viewing, and seeing the matchstick, there is a size reference.  but now I wonder what significance to the scene does a matchstick play?  It does meet the challenge so I''m adjusting my score to a 5 from a 4</td>', 'These are all in proportion - nothing to tell me they are miniature versions of the real thing, other than I know it''s a model.   Doesn''t meet the challenge IMO.   It IS a well lit and well composed photo though.  Upon my second viewing, and seeing the matchstick, there is a size reference.  but now I wonder what significance to the scene does a matchstick play?  It does meet the challenge so I''m adjusting my score to a 5 from a 4', '2004-08-07 13:33:25.000000', NULL, 1),
(848016, 95624, 24511, '<td valign="top">It''s nice to see a photo that demonstrates so well the importance of background.  I  also wondered how much trouble it was to bring a model and find a train track.  Good submission.</td>', 'It''s nice to see a photo that demonstrates so well the importance of background.  I  also wondered how much trouble it was to bring a model and find a train track.  Good submission.', '2004-08-07 13:38:58.000000', NULL, 1),
(848024, 95706, 24511, '<td valign="top">Beautiful lighting of lighthouse.  I found the background blurred and was uncertain if it enhanced the focus on the miniature.  The strong fence lines against the sky competed for  my attention.  I enjoyed searching the dark for white shapes on the forground and details on the house to the right.  Great shot.</td>', 'Beautiful lighting of lighthouse.  I found the background blurred and was uncertain if it enhanced the focus on the miniature.  The strong fence lines against the sky competed for  my attention.  I enjoyed searching the dark for white shapes on the forground and details on the house to the right.  Great shot.', '2004-08-07 13:51:50.000000', NULL, 1),
(848026, 95594, 21554, '<td valign="top">Nice idea and well shot.   A whiskey glass might have been better, though.</td>', 'Nice idea and well shot.   A whiskey glass might have been better, though.', '2004-08-07 13:52:34.000000', NULL, 1),
(848030, 95640, 24511, '<td valign="top">Subtle blending of shapes and color with a well balanced composition.  I love the number of cows depicted (three) giving me a circular scan and the ultra focus and reflection on the cookie raft captain.  Congratulations.</td>', 'Subtle blending of shapes and color with a well balanced composition.  I love the number of cows depicted (three) giving me a circular scan and the ultra focus and reflection on the cookie raft captain.  Congratulations.', '2004-08-07 13:58:22.000000', NULL, 1),
(848032, 95463, 19608, '<td valign="top">Excellent composition!  And exposure.  And Focus.  The colors really pop out of the rich black background.  You have a real winner here - most likely headed for ribbonland.</td>', 'Excellent composition!  And exposure.  And Focus.  The colors really pop out of the rich black background.  You have a real winner here - most likely headed for ribbonland.', '2004-08-07 14:04:04.000000', NULL, 1),
