(849235, 95429, 25208, '<td valign="top">I can''t decide if this meets the challenge, as it doesn''t look very miniturature to me. The background is just blah, and I don''t know why you would submit this picture.</td>', 'I can''t decide if this meets the challenge, as it doesn''t look very miniturature to me. The background is just blah, and I don''t know why you would submit this picture.', '2004-08-08 16:59:31.000000', NULL, 1),
(849238, 95562, 19608, '<td valign="top">Great setup of an excellent set of objects.  The colors you picked work real magic.</td>', 'Great setup of an excellent set of objects.  The colors you picked work real magic.', '2004-08-08 17:03:14.000000', NULL, 1),
(849243, 94308, 19608, '<td valign="top">Your miniature tools are perfect.  The image is very well setup and technically well done.  Perfect exposure and focus.  Composition is a bit centered and I''m not sure the bright yellow background works as well as a very dark or black one would.</td>', 'Your miniature tools are perfect.  The image is very well setup and technically well done.  Perfect exposure and focus.  Composition is a bit centered and I''m not sure the bright yellow background works as well as a very dark or black one would.', '2004-08-08 17:10:59.000000', NULL, 1),
