(849591, 95113, 23294, '<td valign="top">Would have scored really well if the focus was more on the bike, rather than on the shoe. 7.</td>', 'Would have scored really well if the focus was more on the bike, rather than on the shoe. 7.', '2004-08-08 21:57:33.000000', NULL, 1),
(849592, 95702, 17200, '<td valign="top">I''ll give you a 5 just for the title :)</td>', 'I''ll give you a 5 just for the title :)', '2004-08-08 21:58:31.000000', NULL, 1),
