(851936, 95396, 24841, '<td valign="top">Awesome!  I laughed out loud when I saw this, love how it makes me feel.</td>', 'Awesome!  I laughed out loud when I saw this, love how it makes me feel.', '2004-08-10 01:42:44.000000', NULL, 1),
