(851959, 95664, 24841, '<td valign="top">I don''t really get the mimi in this but I couldn''t stop looking at this picture, it is so unbelieveably beautiful, I wish I were there.</td>', 'I don''t really get the mimi in this but I couldn''t stop looking at this picture, it is so unbelieveably beautiful, I wish I were there.', '2004-08-10 01:51:30.000000', NULL, 1),
(851960, 95587, 7751, '<td valign="top">You can still tell the larger bottle is Vodka, but I would have like to see a different angle to provide a better view of the big bottles'' label.</td>', 'You can still tell the larger bottle is Vodka, but I would have like to see a different angle to provide a better view of the big bottles'' label.', '2004-08-10 01:52:33.000000', NULL, 1),
