(853377, 95701, 16301, '<td valign="top">Don''t you just love 4th place? ;)</td>', 'Don''t you just love 4th place? ;)', '2004-08-11 01:11:04.000000', NULL, 0),
(853378, 95629, 19978, '<td valign="top">Thanks to everyone for their comments during the voting. I knew it was a good idea but didn''t like the technical aspects of my composition. A last minute crop probably made the difference. My daughter has since corrected my description - it''s not an American Girl violin, just a miniature instrument that she had on shelf of similar trinkets. We have three full-sized instruments in the house (my wife and daughter both play), so I spent two days shooting them in various settings and lighting, this was the best, though I was not completely happy with it as my pre-submission comments indicate.</td>', 'Thanks to everyone for their comments during the voting. I knew it was a good idea but didn''t like the technical aspects of my composition. A last minute crop probably made the difference. My daughter has since corrected my description - it''s not an American Girl violin, just a miniature instrument that she had on shelf of similar trinkets. We have three full-sized instruments in the house (my wife and daughter both play), so I spent two days shooting them in various settings and lighting, this was the best, though I was not completely happy with it as my pre-submission comments indicate.', '2004-08-11 01:11:33.000000', NULL, 0),
(853379, 95487, 22734, '<td valign="top">Congratulations on your 5th place finish. This is another awesome image that belongs right at the top.</td>', 'Congratulations on your 5th place finish. This is another awesome image that belongs right at the top.', '2004-08-11 01:11:40.000000', NULL, 0),
(853381, 95701, 24896, '<td valign="top">soooo close I was rooting for this one</td>', 'soooo close I was rooting for this one', '2004-08-11 01:13:01.000000', NULL, 0),
